const $=s=>document.querySelector(s);
const roles={owner:'Владелец',seller:'Продавец',manager:'Менеджер',rep:'Торговый представитель',accountant:'Бухгалтер',warehouse:'Склад',dispatcher:'Диспетчер',courier:'Курьер'};
const navItems=['Продажи','Клиенты','Товары','Склад','Закупки','Деньги','Доставка','Отчёты'];
const navRoles={owner:navItems,seller:['Продажи','Клиенты','Товары'],manager:['Продажи','Клиенты','Товары','Деньги','Доставка'],rep:['Мой день','Клиенты','Товары','Деньги'],accountant:['Деньги','Продажи','Закупки','Отчёты'],warehouse:['Склад','Товары','Доставка'],dispatcher:['Доставка'],courier:['Мои доставки','Деньги']};
const paths={Продажи:'M4 4h16v16H4z M8 8h8 M8 12h8 M8 16h4',Клиенты:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2 M9 3a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M18 8v6 M15 11h6',Товары:'M3 7l9-4 9 4v10l-9 4-9-4z M3 7l9 4 9-4 M12 11v10',Склад:'M3 21V9l9-6 9 6v12 M7 21V11h10v10 M7 15h10 M7 18h10',Закупки:'M4 4h2l3 12h10l3-9H7 M10 20h1 M18 20h1',Деньги:'M3 5h18v14H3z M3 9h18 M7 15h4',Доставка:'M3 6h12v11H3z M15 10h4l3 4v3h-7 M6 17v3h3v-3 M17 17v3h3v-3',Отчёты:'M4 3v18h17 M8 16v-5 M13 16V6 M18 16V9'};
let role=new URLSearchParams(location.search).get('role')||'owner',tab='Обзор';if(!roles[role])role='owner';
const icon=n=>`<svg viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[n]||paths.Продажи}"/></svg>`;
const tag=(t,c='')=>`<span class="tag ${c}">${t}</span>`;
const btn=(text,action='',primary=false)=>`<button ${primary?'class="primary"':''} data-action="${action||text}">${text}</button>`;
const panel=(title,body,extra='')=>`<section class="panel"><div class="panel-head"><h2>${title}</h2>${extra}</div>${body}</section>`;
const table=(heads,rows)=>`<div class="table-wrap"><table><thead><tr>${heads.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(c=>`<td>${c}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
const header=(title,sub,action='')=>`<div class="heading"><div><h1>${title}</h1><p>${sub}</p></div>${action?btn(action,action,true):''}</div>`;
const tabs=(values,selected)=>`<div class="tabs" aria-label="Представления">${values.map(t=>`<button data-tab="${t}" class="${t===selected?'selected':''}" aria-pressed="${t===selected}">${t}</button>`).join('')}</div>`;
const filters=()=>`<div class="filters"><input id="table-search" type="search" aria-label="Поиск в таблице" placeholder="Поиск по названию, номеру или клиенту"><button data-action="Фильтры">Фильтры</button><button data-action="Сохранённые представления">Мои представления</button></div>`;
const warning='<div class="note warn">1С, касса и канал отправки документов клиентам пока не выбраны. Подключения и операции ниже показаны только как сценарии.</div>';
const row=(title,desc,action,red=false)=>`<div class="attention-row"><span class="dot ${red?'red':''}"></span><div><strong>${title}</strong><p>${desc}</p></div>${btn(action,title)}</div>`;
function owner(){let body='';if(tab==='Обзор')body=`<div class="filters"><select aria-label="Период"><option>5 ноября · учебный день</option><option>Неделя · пример периода</option></select><button data-action="Сопоставимый период">Сравнить периоды</button><button data-action="Пустой обзор">Без исходных данных</button></div><div class="metrics">${[['Продажи','48 600 ₽','Отгрузки за вычетом возвратов','Продажи и документы'],['Поступило от покупателей','35 200 ₽','Банк, касса и принятые наличные','Поступления и документы'],['Валовая прибыль','12 480 ₽','Маржа 25,7% · учебная себестоимость полная','Расчёт прибыли'],['Долги покупателей','86 400 ₽','Из них 18 600 ₽ просрочено','Долги и документы']].map(m=>`<div class="metric"><div class="metric-label">${m[0]}</div><div class="metric-value">${m[1]}</div><div class="metric-note">${m[2]}</div><button data-action="${m[3]}">Показать исходные документы</button></div>`).join('')}</div><div class="cols">${panel('Требует внимания',row('Порошок «Учебный», 3 кг: осталось 36 шт.','Фактически 72 · резерв 36 · порог 50. Ответственный: закупки.','Открыть товар')+row('Оплата клиента просрочена на 4 дня','Учебный клиент А · задолженность 18 600 ₽ · менеджер.','Открыть долг',true)+row('У сотрудников 9 800 ₽ к сдаче','Курьер: 6 400 ₽ · представитель: 3 400 ₽.','Сверить наличные'))}${panel('Деньги и товар',`<div class="panel-body">${[['Долги поставщикам','42 000 ₽'],['Ближайшие платежи','12 000 ₽'],['Стоимость остатков','235 800 ₽'],['Возвраты за период','1 400 ₽'],['Списания за период','620 ₽'],['Заказы с задержкой','2']].map(x=>`<div class="key-value"><span>${x[0]}</span><strong>${x[1]}</strong></div>`).join('')}<p class="small muted">Чистая прибыль не показана: полнота расходов ещё не подтверждена.</p></div>`)}</div>`;
else if(tab==='Требует внимания')body=`<div class="note">Каждый сигнал содержит причину, цифры и ответственного. Повторные падения в одном эпизоде не создают одинаковые уведомления.</div>${panel('Остатки ниже 50',table(['Товар / склад','Факт','Резерв','Доступно','Ожидается','Действие'],[['<strong>Порошок «Учебный», 3 кг</strong><small>Склад в примере · ПР-001</small>','72 шт.','36 шт.',tag('36 шт.','warn'),'120 шт. · дата не назначена',btn('Разобрать','Порошок «Учебный», 3 кг: осталось 36 шт.')],['<strong>Кондиционер «Учебный», 1 л</strong><small>Склад в примере · КН-002</small>','49 шт.','0',tag('49 шт.','warn'),'Нет заказа поставщику',btn('Создать закупку')]]))}${panel('Заказы и деньги',row('Оплата клиента просрочена на 4 дня','18 600 ₽ · причина: срок оплаты прошёл · менеджер.','Открыть долг',true)+row('Сборка заказа П-104 задерживается','План 12:00 · сейчас 13:20 · склад.','Открыть сборку')+row('Сверка кассы требует проверки','Неизвестный результат запроса не является ошибкой чека.','Открыть обмен',true))}`;
else body=`${panel('Подробные отчёты',`<div class="report-list">${[['Товары','Количество, выручка, прибыль, наличие и оборачиваемость'],['Клиенты','Повторные покупки, задолженность и снижение активности'],['Сотрудники','Продажи, скидки, возвраты и результат визитов'],['Акции','Выручка и прибыль с учётом наличия и сезонности'],['Доставка','Вручение вовремя, отказы, затраты и деньги у сотрудников'],['Деньги','Поступления, выплаты, расходы и взаиморасчёты']].map(r=>`<button data-action="Отчёт: ${r[0]}">${r[0]}<span>${r[1]}</span></button>`).join('')}</div>`)}<div class="note">Каждая итоговая сумма раскрывается до документов. Неполная себестоимость обозначается явно, продажи не смешиваются с оплатами.</div>`;
return header('Рабочее место владельца','ООО · учебный пример · отчёты ИП отдельно')+tabs(['Обзор','Требует внимания','Подробные отчёты'],tab)+body;}
function seller(){return header('Новая продажа','Розница · ИП · покупатель не обязателен','Отложенные продажи')+`<div class="cols"><div><div class="panel"><div class="panel-body"><label class="search-label" for="table-search">Отсканируйте товар или начните вводить название</label><input class="large-search" id="table-search" type="search" placeholder="Штрихкод, артикул или название"></div>${table(['Товар','Цена / шт.','Доступно',''],[['<strong>Порошок «Учебный», 3 кг</strong><small>ПР-001 · упаковка 12 шт.</small>','320 ₽','36 шт.',btn('Добавить','Добавление в корзину')],['<strong>Кондиционер «Учебный», 1 л</strong><small>КН-002 · аромат: нейтральный</small>','180 ₽','49 шт.',btn('Добавить','Добавление в корзину')],['<strong>Мыло «Учебное», 90 г</strong><small>МЛ-003 · базовая единица: штука</small>','60 ₽','180 шт.',btn('Добавить','Добавление в корзину')]])}</div><div class="note">Предлагается сканер в режиме клавиатуры; оборудование пока не выбрано. После добавления товара фокус возвращается в поиск. Черновик сохраняется автоматически в рабочей системе.</div></div>${panel('Корзина · пример продажи',`<div class="panel-body"><div class="key-value"><span>Порошок, 3 кг<br><small>1 шт. × 320 ₽</small></span><strong>320 ₽</strong></div><div class="key-value"><span>Мыло, 90 г<br><small>2 шт. × 60 ₽</small></span><strong>120 ₽</strong></div><div class="key-value"><span>Скидка</span>${btn('По правилам','Скидка')}</div><div class="total"><span>Итого</span><span>440 ₽</span></div><button class="primary full" data-action="Оплата розницы">Перейти к оплате</button><div class="actions">${btn('Отложить','Черновик')}${btn('Возврат по чеку','Возврат')}</div><p class="small muted">Наличные, безналичные или смешанная оплата. Чек формируется кассовым решением.</p></div>`)}</div>`;}
function manager(){return header('Мои заказы','Опт · ООО · предварительная схема учёта','Новый заказ')+filters()+panel('Заказы в работе',table(['Заказ / клиент','Сумма','Оплата','Резерв / сборка','Срок',''],[['<strong>П-104 · Учебный клиент А</strong><small>3 коробки по 12 шт. = 36 шт.</small>','11 520 ₽',tag('Частично · 5 000 ₽','warn'),'36 шт. / ожидает сборки','Сегодня',btn('Открыть','Заказ П-104')],['<strong>П-105 · Учебный клиент Б</strong><small>Минимум опта ещё не настроен</small>','8 200 ₽',tag('Не оплачено'),'Черновик / без резерва','Не назначен',btn('Открыть','Новый заказ')],['<strong>П-106 · Учебный клиент В</strong><small>Повтор предыдущего заказа</small>','4 560 ₽',tag('Не оплачено'),'Нужна проверка цен','Завтра',btn('Проверить','Повторить заказ')]]))+`<div class="cols">${panel('Условия опта',`<div class="panel-body"><div class="key-value"><span>Минимум заказа</span><strong>В штуках · число не задано</strong></div><div class="key-value"><span>Отсрочка</span><strong>Предусмотрена</strong></div><div class="key-value"><span>Скидки</span><strong>По правам и условиям</strong></div><p class="small muted">Сроки, лимиты и сочетание акций требуют настройки владельцем.</p></div>`)}${panel('Быстрые действия',`<div class="panel-body"><div class="actions">${btn('Повторить заказ')}${btn('Счёт и реквизиты')}${btn('Запросить скидку','Скидка')}</div><p class="small muted">Перед отправкой документа проверяются получатель, организация и версия реквизитов.</p></div>`)}</div>`;}
function rep(){return header('Мой день','Торговый представитель · пример маршрута визитов','Новый заказ')+`<div class="mobile-flow"><div class="cash-strip"><div><span>Наличные у меня</span><strong>3 400 ₽</strong></div>${btn('Приём и сдача','Наличные сотрудника')}</div><div class="queue-summary"><span><strong>3</strong> визита по плану</span><span><strong>1</strong> завершён</span><span>Личный план: ${btn('Открыть','План представителя')}</span></div>${panel('Визиты сегодня',`<div class="visit"><div class="visit-time">10:00</div><div><h3>Учебная торговая точка А</h3>${tag('Визит завершён','good')}<p>Заказ передан менеджеру. Доставка курьером.</p>${btn('Результат визита')}</div></div><div class="visit"><div class="visit-time">12:30</div><div><h3>Учебная торговая точка Б</h3><p>Последняя покупка 10 дней назад · долг 3 400 ₽.</p><div class="actions">${btn('Повторить заказ','Повторить заказ',true)}${btn('Принять наличные','Наличные сотрудника')}${btn('Результат визита')}</div></div></div><div class="visit"><div class="visit-time">15:00</div><div><h3>Учебная торговая точка В</h3><p>Задача: предложить актуальные акции.</p>${btn('Каталог и акции')}</div></div>`)}<div class="note">Без сети сохраняется черновик на устройстве. Цена и наличие проверяются после подключения. Резерв до подтверждения сервера не гарантируется.</div><p class="screen-note">Представитель может принять наличные, но не получает задание на перевозку товара.</p></div>`;}
function accountant(){return header('Оплаты и сверка','Бухгалтер · раздельные расчёты ООО и ИП','Сопоставить платёж')+warning+filters()+panel('Поступления к обработке',table(['Основание','Источник','Сумма','Состояние',''],[['<strong>П-104 · Учебный клиент А</strong><small>Платёж банка</small>','Банковская выписка','5 000 ₽',tag('Пример сопоставления'),btn('Сверить','Сопоставить платёж')],['<strong>Без основания</strong><small>Неопознанное поступление</small>','Банковская выписка','2 100 ₽',tag('Найти заказ','warn'),btn('Разобрать','Сопоставить платёж')]]))+panel('Наличные у сотрудников',table(['Сотрудник','Принято','Сдано','К сдаче',''],[['Курьер в примере','9 000 ₽','2 600 ₽','6 400 ₽',btn('Принять сдачу','Сдача наличных')],['Представитель в примере','3 400 ₽','0 ₽','3 400 ₽',btn('Принять сдачу','Сдача наличных')]]))+`<div class="note">Получение наличных от клиента погашает долг один раз. Сдача сотрудником в кассу - внутреннее перемещение, без повторного поступления от клиента.</div>`;}
function warehouse(){return header('Работа склада','Склад при магазине · собственник товара учитывается отдельно','Принять поставку')+`<div class="queue-summary"><span><strong>2</strong> к сборке</span><span><strong>1</strong> ожидаемая поставка</span><span><strong>1</strong> возврат на проверке</span></div>`+filters()+panel('Очередь сборки',table(['Заказ','Нужно собрать','Срок','Состояние',''],[['<strong>П-104</strong><small>Порошок «Учебный», 3 кг</small>','3 кор. × 12 = 36 шт.','12:00',tag('Срок прошёл','bad'),btn('Взять в работу','Сборка',true)],['<strong>П-108</strong><small>4 товарные позиции</small>','18 шт.','15:00',tag('К сборке'),btn('Открыть','Сборка')]]))+`<div class="cols">${panel('Возврат на проверке',`<div class="panel-body"><h3>В-012 · кондиционер, 2 шт.</h3><p class="small muted">Одна повреждённая крышка. Товар в карантине и недоступен для продажи.</p>${btn('Проверить состояние','Возврат')}</div>`)}${panel('Остатки и движения',`<div class="panel-body"><div class="key-value"><span>Факт / резерв / доступно</span><strong>Раздельно</strong></div><p class="small muted">Каждое движение имеет документ и автора. Себестоимость скрыта от склада.</p>${btn('Открыть остатки','Остатки')}</div>`)}</div>`;}
function dispatcher(){return header('Доставка','Свои курьеры · самовывоз отдельно','Назначить курьера')+filters()+panel('Задания на сегодня',table(['Заказ / получение','Мест','Интервал','Готовность','Курьер',''],[['<strong>П-104 · доставка</strong><small>Учебный адрес А, Астрахань</small>','3','14:00-16:00',tag('Собирается','warn'),'Не назначен',btn('Открыть','Назначить курьера')],['<strong>П-109 · доставка</strong><small>Учебный адрес Б, Астрахань</small>','2','12:00-14:00',tag('В пути'),'Курьер в примере',btn('Подробности','Доставка')],['<strong>П-110 · самовывоз</strong><small>Выдача в магазине</small>','1','После 15:00',tag('Готов к выдаче','good'),'Не требуется',btn('Подробности','Самовывоз')]]))+panel('Проблемы доставки',row('Неудачная попытка: клиент не на месте','П-103 · товар у курьера · требуется перенос или возврат на склад.','Разобрать','red'))+`<div class="note">Отказ клиента не возвращает товар в доступный остаток. Нужны физическая приёмка и проверка состояния.</div>`;}
function courier(){return header('Мои доставки','Курьер · только назначенные задания')+`<div class="mobile-flow"><div class="cash-strip"><div><span>Наличные у меня</span><strong>6 400 ₽</strong></div>${btn('Сверить и сдать','Сдача наличных')}</div>${panel('Ближайшая доставка',`<div class="panel-body"><div class="heading"><div><h2>П-109 · Учебный клиент</h2><p>Сегодня, 12:00-14:00</p></div>${tag('В пути')}</div><h3>Учебный адрес Б, Астрахань</h3><p class="small muted">Адрес и контакт вымышлены. В рабочей системе здесь будут данные только назначенного заказа.</p><div class="actions">${btn('Открыть в картах','Контакт доставки')}${btn('Позвонить','Контакт доставки')}</div><div class="key-value"><span>Количество мест</span><strong>2 коробки</strong></div><div class="key-value"><span>К получению наличными</span><strong>2 600 ₽</strong></div><div class="key-value"><span>Статус оплаты</span>${tag('Не оплачено','warn')}</div><div class="actions">${btn('Принять наличные','Наличные сотрудника',true)}${btn('Вручить товар','Вручение')}${btn('Не удалось доставить')}</div></div>`)}<div class="note">Вручение товара и приём оплаты подтверждаются отдельно. При неизвестном результате кассы нельзя вслепую повторять чек.</div></div>`;}
const renderers={owner,seller,manager,rep,accountant,warehouse,dispatcher,courier};
function render(){const active={owner:'Отчёты',seller:'Продажи',manager:'Продажи',rep:'Мой день',accountant:'Деньги',warehouse:'Склад',dispatcher:'Доставка',courier:'Мои доставки'}[role];$('#role').value=role;$('#nav').innerHTML=navRoles[role].map(n=>`<button class="nav-button ${n===active?'active':''}" data-nav="${n}">${icon(n)}${n}</button>`).join('');$('#main').innerHTML=`<div class="topline"><span>Рабочее место · ${roles[role]}</span><span class="user-tag"><span class="avatar">${roles[role][0]}</span>Учебный просмотр</span></div>`+renderers[role]();const input=$('#table-search');if(input)input.addEventListener('input',()=>{const q=input.value.toLocaleLowerCase('ru');document.querySelectorAll('tbody tr').forEach(tr=>tr.hidden=!tr.textContent.toLocaleLowerCase('ru').includes(q))});}
const details={
'Порошок «Учебный», 3 кг: осталось 36 шт.':['Сигнал: доступно меньше 50', '<p>Учебный пример: физический остаток 72 шт., активный резерв 36 шт. Доступно: <strong>36 шт.</strong> Порог: 50 шт.</p><p>Ответственный: закупки. Ожидается 120 шт., но эта поставка не увеличивает доступное количество до приёмки.</p><ol><li>Проверить движения и резервы по складу.</li><li>Проверить уже заказанное у поставщика.</li><li>Создать предложение закупки с учётом срока поставки и упаковки.</li></ol><p>Уведомление только внутри CRM. База расчёта по организации, SKU и складу - предложение.</p>'],
'Пустой обзор':['Когда магазин ещё не начал работу','<div class="empty"><h2>Данных для отчёта пока нет</h2><p>Создайте склад, загрузите каталог и начальные остатки. После проведённых операций здесь появятся продажи, деньги и задолженность.</p></div><p>Отсутствие данных не показывается как нулевая прибыль. Сравнение с прошлым периодом и планом недоступно до их появления.</p>'],
'Расчёт прибыли':['Валовая прибыль до исходных документов','<p>Учебный пример: выручка после возвратов 48 600 ₽, себестоимость 36 120 ₽. Валовая прибыль 12 480 ₽, маржа 25,7%.</p><p>В рабочей системе сумма раскрывается до строк отгрузок и возвратов с одной налоговой базой. При неизвестной себестоимости части строк показываются покрытие и неполнота результата.</p>'],
'Оплата розницы':['Оплата и выдача','<ol><li>Выбрать наличные, безналичные либо смешанную оплату.</li><li>Проверить итог и суммы по каждому способу; для наличных рассчитать сдачу.</li><li>Для маркируемого товара считать необходимые коды.</li><li>Подтвердить расчёт и запросить чек в выбранном кассовом решении.</li><li>Отдельно показать фискализацию и отправку чека покупателю.</li></ol><p>При тайм-ауте сохранить операцию со статусом «Результат уточняется» и сверить её, не создавать второй расчёт. Провайдер пока не выбран.</p>'],
'Добавление в корзину':['Быстрое добавление товара','<p>В рабочей CRM сканер определяет SKU и упаковку. Сотрудник вводит количество, при необходимости меняет разрешённую единицу продажи. Сервер проверяет актуальную цену и доступность.</p><p>Коэффициент упаковки сохраняется в строке: три коробки по 12 списывают 36 штук независимо от последующего изменения карточки товара.</p>'],
'Повторить заказ':['Проверка повторного заказа','<p>Новый черновик собирается из истории клиента, но с текущими условиями.</p>'+table(['Позиция','Было','Сейчас'],[['Порошок, 3 кг','300 ₽ / шт.','320 ₽ / шт.'],['Кондиционер, 1 л','60 шт.','49 шт. доступно']])+'<p>Изменения цены и доступности выделяются до подтверждения. Недоступная строка не удаляется молча. Резерв создаёт только сервер после успешной проверки.</p>'],
'Наличные сотрудника':['Приём денег от клиента','<ol><li>Выбрать клиента и основание: один или несколько заказов/долгов.</li><li>Проверить сумму, получателя и способ расчёта.</li><li>Провести приём наличных с уникальным ключом и согласованным кассовым процессом.</li><li>Записать деньги на ответственность сотрудника; погасить долг один раз.</li><li>Показать отдельно статус чека и отправки.</li></ol><p>Курьер и представитель могут принимать наличные. Только курьер доставляет товар. Без сети нельзя обещать завершённую фискализацию или выдавать черновик за подтверждённый платёж.</p>'],
'Сдача наличных':['Сверка и сдача в кассу','<p>Показать поступления от покупателей по сотруднику, суммы возвратов и прошлые сдачи. Сотрудник передаёт наличные, кассир/бухгалтер подтверждает фактически принятую сумму.</p><p>Расхождение сохраняется с причиной и ответственным. Сдача - внутреннее перемещение денег, она не повторяет клиентскую оплату и не увеличивает выручку.</p>'],
'Счёт и реквизиты':['Подготовка отправки клиенту','<p>Сначала показываются получатель, выбранная организация, актуальная версия реквизитов, документ и канал отправки. Только затем сотрудник подтверждает отправку.</p><p>Счёт на оплату, реквизиты и фискальный чек - разные документы. Статусы сформирован / фискализирован / отправлен не объединяются. Канал пока не выбран.</p>'],
'Результат визита':['Результат визита представителя','<p>Варианты: заказ оформлен; договорились вернуться; клиент отказался; точка закрыта. Для отказа выбрать причину и при необходимости короткий комментарий. Следующая задача имеет дату и ответственного.</p><p>Количество визитов не считается продажами. Личный результат считается по согласованной атрибуции отгрузок без двойного счёта с менеджером.</p>'],
'Возврат':['Частичный возврат','<ol><li>Найти исходную продажу и допустимое к возврату количество.</li><li>Принять товар на проверку, зафиксировать состояние и причину.</li><li>Отдельно оформить расчёт с покупателем и необходимый кассовый документ.</li><li>После проверки перевести пригодное в доступный остаток; повреждённое оставить в карантине.</li></ol><p>Два одновременных возврата не могут превысить исходное количество. Исходная цена и себестоимость сохраняются для корректной аналитики.</p>'],
'Сборка':['Задание склада','<p>По каждой строке видны требуемое количество, упаковка, партия и срок при применимости. Сканирование подтверждает фактический SKU, недостача или повреждение фиксируется отдельно.</p><p>Взятие задания защищено от параллельной обработки. Закупочные цены сотруднику склада не выдаются. Сборка не равна отгрузке.</p>'],
'Скидка':['Разрешённая скидка','<p>Порядок применения оптовой/персональной/акционной цены и ручной скидки определяется владельцем. До настройки нельзя выбирать случайные лимиты.</p><p>При выходе за полномочия или нижнюю границу маржи нужен запрос согласования с причиной и версией заказа. Изменение строк отменяет устаревшее согласование.</p>'],
'Вручение':['Вручить товар','<p>Проверить заказ и количество мест. Подтвердить фактическое вручение, при разрешённом частичном вручении указать строки и причины недовложения.</p><p>Статус оплаты не меняется автоматически. Неполученные товары остаются в ответственности курьера до приёмки на складе.</p>'],
'Не удалось доставить':['Неудачная попытка','<p>Выбрать причину: клиент отсутствует, отказ, неверный адрес или другая причина. Указать комментарий и передать диспетчеру для переноса либо возврата.</p><p>Товар не возвращается в доступный остаток до физической приёмки. Повторная отправка результата не создаёт второе событие.</p>'],
'Контакт доставки':['Контакт назначенного заказа','<p>В рабочей системе кнопки откроют карты и телефон конкретной назначенной доставки. Здесь данные учебные, поэтому звонок и переход к вымышленному адресу не выполняются.</p>'],
'Сопоставить платёж':['Проверка платежа','<p>Выбрать подтверждённое банковское или кассовое поступление и распределить его по одному или нескольким заказам. Остаток суммы становится нераспределённым авансом, а не теряется.</p><p>Скриншот перевода не заменяет подтверждение. Повторный импорт по внешнему идентификатору не создаёт второй платёж.</p>'],
'Заказ П-104':['Заказ П-104: независимые состояния','<p>Учебный пример: 3 коробки × 12 шт. × 320 ₽ = 11 520 ₽. Принято 5 000 ₽, остаток к оплате 6 520 ₽. Если отгрузки ещё нет, это остаток заказа к оплате, а не автоматически признанная дебиторская задолженность.</p><p>Резерв: 36 шт. Сборка: ожидает. Отгрузка: нет. Доставка: не назначена. Чек: зависит от согласованной схемы расчёта.</p>'],
'Черновик':['Сохранение черновика','<p>В рабочей системе сохранение выполняется автоматически, с отметкой времени. Незавершённая операция восстанавливается после перезагрузки. Локальный черновик не создаёт резерв или подтверждённую оплату.</p>'],
'Сопоставимый период':['Сравнение без ложных выводов','<p>Сравниваются периоды одинаковой длины и состава рабочих дней. Для товаров и акций дополнительно учитываются дни наличия и сезонность. План показывается только после его ввода.</p>'],
'План представителя':['Личный план и результат','<p>План продаж, выполненные визиты, новые покупающие клиенты, повторные продажи и просрочка закреплённых клиентов. План не задан - показываем «Не задан», а не процент от случайного значения.</p>'],
'Фильтры':['Фильтры списка','<p>Предлагаемые фильтры зависят от раздела: период, склад, статус, ответственный в разрешённой области, клиент и просрочка. Статусы оплаты, сборки и доставки выбираются отдельно.</p>'],
'Сохранённые представления':['Сохранённые представления','<p>Сохранить набор фильтров, колонок и сортировки с понятным названием, например «Мои просроченные оплаты». Представление не расширяет права и не закрепляет устаревший результат.</p>']};
function show(title,body){$('#detail-title').textContent=title;$('#detail-content').innerHTML=body+'<div class="note">Это описание сценария прототипа. Рабочая операция не выполняется.</div>';$('#detail').showModal();}
function openAction(action){if(details[action])show(...details[action]);else if(action.startsWith('Отчёт:'))show(action,`<p>В отчёте предусмотрены период, фильтры, итоги и раскрытие до первичных документов. Формулы, даты признания, возвраты и правила полноты описаны в проектной спецификации аналитики.</p><p><a href="../docs/analytics.md">Открыть спецификацию аналитики</a></p>`);else show(action,`<p>Рабочий сценарий «${action}» входит в проектирование. В прототипе показаны расположение действия и переход к подробностям; выполнение требует серверного учёта и согласованных настроек.</p><p><a href="../docs/role-workflows.md">Сценарии всех ролей</a> · <a href="../docs/acceptance.md">Критерии приёмки</a></p>`);}
$('#role').addEventListener('change',e=>{role=e.target.value;tab='Обзор';if(location.protocol!=='file:')history.replaceState(null,'','?role='+role);render()});$('#close').onclick=()=>$('#detail').close();document.addEventListener('click',e=>{const t=e.target.closest('[data-tab]');if(t){tab=t.dataset.tab;render();return}const a=e.target.closest('[data-action]');if(a){openAction(a.dataset.action);return}const n=e.target.closest('[data-nav]');if(n)show('Раздел «'+n.dataset.nav+'»',`<p>Навигация рабочего места ${roles[role].toLowerCase()} ограничена разрешёнными действиями. Предложенная карта разделов и переходов описана в спецификации.</p><p><a href="../docs/role-workflows.md">Карта разделов и рабочих мест</a></p>`)});render();
